function wireInlineCalculators(container) {
  if (!container) return;
  container.querySelectorAll('[data-inline-calc="match"]').forEach(calc => {
    const inputs = calc.querySelectorAll('input[data-calc]');
    const result = calc.querySelector('[data-calc="match-result"]');
    const update = () => {
      const amount = parseFloat(calc.querySelector('[data-calc="match-amount"]').value) || 0;
      const years = parseFloat(calc.querySelector('[data-calc="match-years"]').value) || 0;
      const rate = (parseFloat(calc.querySelector('[data-calc="match-rate"]').value) || 0) / 100;
      // FV of annuity: PMT × [(1+r)^n − 1] / r
      const fv = rate === 0 ? amount * years : amount * (Math.pow(1 + rate, years) - 1) / rate;
      const totalMatched = amount * years;
      const compoundGrowth = fv - totalMatched;
      result.innerHTML = `
        <span class="calc-result-headline">${fmtMoneyFull(fv)}</span>
        <span class="calc-result-detail">Total match received: ${fmtMoneyFull(totalMatched)}. Compound growth on top: ${fmtMoneyFull(compoundGrowth)}. This is the real lifetime value of the matching dollars — not just the headline annual figure.</span>
      `;
      // Stop event propagation on input to avoid closing the node
    };
    inputs.forEach(i => {
      i.addEventListener('input', update);
      i.addEventListener('click', e => e.stopPropagation()); // don't toggle node
    });
    update();
  });
}

function __debounce(fn, ms) {
  if (_debouncedCache.has(fn)) return _debouncedCache.get(fn);
  let timer;
  const wrapped = function() {
    const args = arguments, self = this;
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(self, args), ms);
  };
  _debouncedCache.set(fn, wrapped);
  return wrapped;
}

function calcCompound() {
  const pv = $val('ci-pv', 0);
  const pmt = $val('ci-pmt', 500);
  const rateAnnual = $val('ci-rate', 7) / 100;
  const years = $val('ci-years', 30);
  const rMonthly = rateAnnual / 12;
  const n = years * 12;
  const fvPrincipal = pv * Math.pow(1 + rMonthly, n);
  const fvContribs = rMonthly === 0
    ? pmt * n
    : pmt * (Math.pow(1 + rMonthly, n) - 1) / rMonthly;
  const fv = fvPrincipal + fvContribs;
  const totalContributed = pv + pmt * n;
  const totalGrowth = fv - totalContributed;
  document.getElementById('ci-result').innerHTML = `
    <span class="calc-result-headline">${fmtMoneyFull(fv)}</span>
    <span class="calc-result-detail">Total contributed: ${fmtMoneyFull(totalContributed)} · Investment growth: ${fmtMoneyFull(totalGrowth)} (${((totalGrowth / Math.max(totalContributed, 1)) * 100).toFixed(0)}% of contributions)</span>
  `;
  renderCompoundChart({ pv, pmt, rateAnnual, years, containerId: 'ci-chart' });
}

function calcRule72() {
  const r = $val('r72-rate', 7);
  const r2 = r / 100;
  if (r <= 0) {
    document.getElementById('r72-result').innerHTML = '<span class="calc-result-detail">Rate must be positive.</span>';
    return;
  }
  const t2_approx = 72 / r;
  const t2_exact = Math.log(2) / Math.log(1 + r2);
  const t3_approx = 114 / r;
  const t3_exact = Math.log(3) / Math.log(1 + r2);
  const t4_approx = 144 / r;
  const t4_exact = Math.log(4) / Math.log(1 + r2);
  document.getElementById('r72-result').innerHTML = `
    <table class="calc-table">
      <tr><th>Multiplier</th><th>Rule estimate</th><th>Exact</th></tr>
      <tr class="highlight"><td>2× (double)</td><td>${t2_approx.toFixed(1)} yr</td><td>${t2_exact.toFixed(1)} yr</td></tr>
      <tr><td>3× (triple)</td><td>${t3_approx.toFixed(1)} yr</td><td>${t3_exact.toFixed(1)} yr</td></tr>
      <tr><td>4× (quadruple)</td><td>${t4_approx.toFixed(1)} yr</td><td>${t4_exact.toFixed(1)} yr</td></tr>
    </table>
    <span class="calc-result-detail" style="display:block;margin-top:10px;">At ${r}% real, a dollar invested today doubles in ${t2_exact.toFixed(1)} years.</span>
  `;
}

function calcSavingsRate() {
  const s = $val('sr-rate', 25) / 100;
  const r = $val('sr-return', 5) / 100;
  const wr = $val('sr-wr', 4) / 100;
  const ss = $val('sr-ss', 0);
  const expenses = $val('sr-expenses', 60000);
  if (s <= 0 || s >= 1 || r <= 0 || wr <= 0) {
    document.getElementById('sr-result').innerHTML = '<span class="calc-result-detail">Inputs must be in valid range (savings rate &gt; 0% and &lt; 100%, returns &gt; 0%).</span>';
    return;
  }
  const k = 1 / wr; // target portfolio multiple of expenses
  const yearsToFI = Math.log(1 + k * r * (1 - s) / s) / Math.log(1 + r);
  // SS overlay: reduces portfolio needed by capitalized value of expected SS at WR
  let ssNote = '';
  let yearsWithSS = null;
  if (ss > 0 && expenses > 0) {
    const expensesCoveredBySS = Math.min(ss, expenses);
    const remainingExpenses = Math.max(0, expenses - expensesCoveredBySS);
    const reducedK = remainingExpenses / expenses; // fraction of target still needed
    if (reducedK > 0) {
      const effectiveK = k * reducedK;
      yearsWithSS = Math.log(1 + effectiveK * r * (1 - s) / s) / Math.log(1 + r);
      ssNote = `<span class="calc-result-detail" style="display:block;margin-top:10px;">With $${ss.toLocaleString()}/yr expected Social Security (today's dollars) covering ${(expensesCoveredBySS/expenses*100).toFixed(0)}% of $${expenses.toLocaleString()}/yr expenses, your portfolio target shrinks proportionally — financial independence drops to <strong>${yearsWithSS.toFixed(1)} years</strong>. SS reduces the multiple-of-expenses target rather than accelerating accumulation directly. Caveat: this assumes SS arrives at FI date and at the projected real benefit; in practice SS starts at 62–70 and FI may precede claiming age, requiring a "bridge" portfolio for the gap.</span>`;
    } else {
      ssNote = `<span class="calc-result-detail" style="display:block;margin-top:10px;">Expected Social Security ($${ss.toLocaleString()}/yr) exceeds annual expenses ($${expenses.toLocaleString()}/yr) — by this model you'd hit FI immediately on SS alone, but in practice SS only starts at claiming age (62–70). Build a bridge portfolio for years between target FI date and claiming.</span>`;
    }
  }
  // Build comparison table
  const rates = [10, 20, 30, 40, 50, 60, 70];
  let rows = '';
  rates.forEach(pct => {
    const sx = pct / 100;
    const y = Math.log(1 + k * r * (1 - sx) / sx) / Math.log(1 + r);
    const isCurrent = Math.abs(pct - s * 100) < 0.5;
    rows += `<tr class="${isCurrent ? 'highlight' : ''}"><td>${pct}%</td><td>${y.toFixed(1)} yr</td></tr>`;
  });
  document.getElementById('sr-result').innerHTML = `
    <span class="calc-result-headline">${yearsToFI.toFixed(1)} years to FI</span>
    <span class="calc-result-detail">From a zero starting balance, assuming constant income, savings rate, and ${(r*100).toFixed(1)}% real return, with a ${(wr*100).toFixed(2)}% safe withdrawal target.</span>
    <table class="calc-table" style="margin-top:14px;">
      <tr><th>Savings rate</th><th>Years to FI</th></tr>
      ${rows}
    </table>
    ${ssNote}
  `;
}

function calcRealNominal() {
  const nom = $val('rn-nominal', 10) / 100;
  const inf = $val('rn-inflation', 3) / 100;
  const real = (1 + nom) / (1 + inf) - 1;
  const approx = nom - inf;
  document.getElementById('rn-result').innerHTML = `
    <span class="calc-result-headline">${(real * 100).toFixed(2)}%</span>
    <span class="calc-result-detail">Real return (exact Fisher equation). Linear approximation (nominal − inflation): ${(approx * 100).toFixed(2)}%. Difference: ${((real - approx) * 100).toFixed(3)} percentage points — small at these rates but compounds over decades.</span>
  `;
}

function calcSequence() {
  const pv = $val('seq-pv', 1000000);
  const wd = $val('seq-wd', 40000);
  const strategy = (document.getElementById('seq-strategy') || {}).value || 'fixed';
  const inflation = 0.03;
  // Build two 30-year return sequences with same arithmetic mean
  const badYears = [-20, -10, -5];
  const goodYears = [-5, -10, -20];
  const fillerRate = (7 * 30 - (badYears.reduce((a, b) => a + b, 0))) / 27;
  const badSeq = badYears.concat(Array(27).fill(fillerRate));
  const goodSeq = Array(27).fill(fillerRate).concat(goodYears);

  // Withdrawal strategy variants:
  // 'fixed' — constant real (inflation-indexed dollar amount)
  // 'flexible' — cut 25% in years following a negative return
  // 'guardrails' — Guyton-Klinger: cut 10% if WR > initial × 1.2; raise 10% if WR < initial × 0.8
  // Returns end-of-year balance path (length seq.length + 1, starting at pv).
  function simulate(seq) {
    let bal = pv;
    let withdrawal = wd;
    const initialWR = wd / pv;
    let prevRet = 0;
    const path = [pv];
    let depleted = null;
    for (let y = 0; y < seq.length; y++) {
      let actualWD = withdrawal;
      if (strategy === 'flexible' && prevRet < 0) {
        actualWD = withdrawal * 0.75;
      } else if (strategy === 'guardrails' && bal > 0) {
        const currentWR = withdrawal / bal;
        if (currentWR > initialWR * 1.2) actualWD = withdrawal * 0.9;
        else if (currentWR < initialWR * 0.8) actualWD = withdrawal * 1.1;
      }
      bal -= actualWD;
      if (bal < 0) {
        depleted = y + 1;
        // Fill remaining years with $0 so the chart path is well-defined.
        while (path.length <= seq.length) path.push(0);
        return { ending: 0, depleted, path };
      }
      bal *= 1 + seq[y] / 100;
      prevRet = seq[y];
      withdrawal *= 1 + inflation;
      path.push(bal);
    }
    return { ending: bal, depleted: null, path };
  }
  const bad = simulate(badSeq);
  const good = simulate(goodSeq);
  const badEnd = bad.depleted ? `Depleted in year ${bad.depleted}` : fmtMoneyFull(bad.ending);
  const goodEnd = good.depleted ? `Depleted in year ${good.depleted}` : fmtMoneyFull(good.ending);
  const stratLabel = strategy === 'fixed' ? 'Fixed real withdrawal' : strategy === 'flexible' ? 'Flexible (25% cuts after down years)' : 'Guyton-Klinger guardrails';
  document.getElementById('seq-result').innerHTML = `
    <table class="calc-table">
      <tr><th>Scenario</th><th>Nominal ending balance after 30 yr</th></tr>
      <tr><td>Bad sequence (losses early)</td><td>${badEnd}</td></tr>
      <tr class="highlight"><td>Good sequence (losses late)</td><td>${goodEnd}</td></tr>
    </table>
    <span class="calc-result-detail" style="display:block;margin-top:10px;">Strategy: <strong>${stratLabel}</strong>. Identical 7% nominal arithmetic-mean returns over 30 years; same starting inflation-indexed withdrawal schedule. Balances are in nominal (future) dollars — purchasing power 30 years out is roughly 40% lower at 3% inflation. The ordering of returns alone produces the gap. Flexible and guardrails strategies materially reduce the bad-sequence damage by cutting spending in down years, at the cost of accepting lower realized lifestyle. The 'what this doesn't model' note: actual market returns cluster and are far more volatile than this smoothed pedagogical demonstration; historical-cycles or Monte Carlo simulation give better distribution shapes (planned for the next sub-phase).</span>
  `;
  renderSequenceChart({ badPath: bad.path, goodPath: good.path, pv, containerId: 'seq-chart' });
}

function calcMuniTEY() {
  const muniYield = $val('muni-yield', 4.0) / 100;
  const treasuryYield = $val('muni-treasury', 4.3) / 100;
  const fedRate = $val('muni-fed', 37) / 100;
  const stateRate = $val('muni-state', 9.3) / 100;
  const inState = ((document.getElementById('muni-instate') || {}).value || 'yes') === 'yes';
  const niitApplies = ((document.getElementById('muni-niit') || {}).value || 'no') === 'yes';

  // Combined rate the Treasury yield gets taxed at = fed + (state) + (NIIT)
  // Munis: federal-exempt; in-state munis also state-exempt; NIIT does NOT apply to muni interest (IRC §1411).
  const treasuryCombinedRate = fedRate + stateRate + (niitApplies ? 0.038 : 0);
  const muniEffectiveRate = inState ? 0 : stateRate; // out-of-state munis taxed by your state but not federal
  const muniAfterTaxYield = muniYield * (1 - muniEffectiveRate);
  const treasuryAfterTaxYield = treasuryYield * (1 - treasuryCombinedRate);
  const muniTEY = muniYield / Math.max(0.0001, 1 - treasuryCombinedRate); // muni's yield in pre-tax terms vs Treasury

  const muniWins = muniAfterTaxYield > treasuryAfterTaxYield;
  const gap = Math.abs(muniAfterTaxYield - treasuryAfterTaxYield) * 100;

  document.getElementById('muni-result').innerHTML = `
    <table class="calc-table">
      <tr><th>Yield comparison</th><th>Pre-tax</th><th>After-tax (your rates)</th></tr>
      <tr class="${muniWins ? 'highlight' : ''}"><td>Muni bond (${inState ? 'in-state, fed + state exempt' : 'out-of-state, fed exempt only'})</td><td>${(muniYield*100).toFixed(2)}%</td><td>${(muniAfterTaxYield*100).toFixed(2)}%</td></tr>
      <tr class="${!muniWins ? 'highlight' : ''}"><td>Treasury (taxed at ${(treasuryCombinedRate*100).toFixed(1)}% combined${niitApplies ? ', incl. NIIT' : ''})</td><td>${(treasuryYield*100).toFixed(2)}%</td><td>${(treasuryAfterTaxYield*100).toFixed(2)}%</td></tr>
    </table>
    <span class="calc-result-detail" style="display:block;margin-top:10px;">
      <strong>Muni taxable-equivalent yield:</strong> ${(muniTEY*100).toFixed(2)}% — the pre-tax yield a fully-taxable bond would need to match this muni after tax. <strong>${muniWins ? 'Munis-in-taxable wins' : 'Treasury-in-tax-deferred wins'} by ${gap.toFixed(0)} bps after-tax.</strong>
      ${muniWins
        ? ' For HNW households in high-state-tax jurisdictions, this is the standard pattern that breaks the "bonds in tax-deferred" rule from the matrix above — the muni-in-taxable yield, after federal-and-state exemption, exceeds the Treasury-in-tax-deferred yield once your combined marginal rate is high enough. The 3-asset matrix calculator above treats all bonds as ordinary-taxed in taxable and so understates this option; full muni integration as a 4th asset is a Phase 7 deliverable (adjacent-vehicles theme). Until then, run the matrix at your bond allocation × your non-muni fraction, and treat the muni fraction as a separate taxable-only sleeve sized to your after-tax-yield advantage.'
        : ' At your rates, the Treasury wins after-tax — the standard "bonds in tax-deferred" rule from the matrix above applies cleanly to your situation. The muni case is sensitive to combined rate: at federal rates below ~32% or in no-state-tax jurisdictions, Treasury after-tax frequently wins; at federal ≥35% with material state tax, munis frequently win.'
      }
      The NIIT (IRC §1411) applies to investment income above the income threshold but specifically does NOT apply to muni interest, which is one of the structural advantages this calculator captures.
    </span>
  `;
}

function calcAssetLocation() {
  const pv = $val('al-pv', 1000000);
  const years = $val('al-years', 30);
  // Asset allocations
  const stockPct = $val('al-stock', 60) / 100;
  const bondPct = $val('al-bond', 30) / 100;
  const reitPct = $val('al-reit', 10) / 100;
  // Account capacities
  const tradPct = $val('al-trad', 50) / 100;
  const rothPct = $val('al-roth', 20) / 100;
  const taxablePct = $val('al-tax', 30) / 100;
  // Returns
  const sret = $val('al-sret', 6) / 100;
  const bret = $val('al-bret', 2) / 100;
  const rret = $val('al-rret', 5) / 100;
  // Tax rates
  const ordRate = $val('al-ord', 32) / 100;
  const futureOrd = $val('al-future-ord', 22) / 100;
  const ladderRate = $val('al-ladder-rate', 12) / 100;  // CL336 — Roth-ladder integration
  const ltcgRate = $val('al-ltcg', 15) / 100;

  const allocTotal = stockPct + bondPct + reitPct;
  const acctTotal = tradPct + rothPct + taxablePct;
  const tolerance = 0.005;
  let validationNote = '';
  if (Math.abs(allocTotal - 1) > tolerance) {
    validationNote += `<br>⚠ Asset allocation sums to ${(allocTotal*100).toFixed(0)}% (should be 100%).`;
  }
  if (Math.abs(acctTotal - 1) > tolerance) {
    validationNote += `<br>⚠ Account capacity sums to ${(acctTotal*100).toFixed(0)}% (should be 100%).`;
  }

  // Terminal value per $1 invested, by (asset, account, rate-regime).
  // CL336 — compute under both no-ladder and with-ladder future-ordinary rates.
  const realizationFraction = 0.10;
  function computeRegime(rateAtWithdrawal) {
    const termTrad = (r) => Math.pow(1 + r, years) * (1 - rateAtWithdrawal);
    const termRoth = (r) => Math.pow(1 + r, years);
    const termTaxableStock = (r) => Math.pow(1 + r * (1 - realizationFraction * ltcgRate), years);
    const termTaxableOrd = (r) => Math.pow(1 + r * (1 - ordRate), years);
    return {
      Stocks: { Traditional: termTrad(sret), Roth: termRoth(sret), Taxable: termTaxableStock(sret) },
      Bonds:  { Traditional: termTrad(bret), Roth: termRoth(bret), Taxable: termTaxableOrd(bret) },
      REITs:  { Traditional: termTrad(rret), Roth: termRoth(rret), Taxable: termTaxableOrd(rret) }
    };
  }
  const matrixNoLadder = computeRegime(futureOrd);
  const matrixLadder = computeRegime(ladderRate);
  // Primary regime for display = no-ladder (matches pre-CL336 behavior).
  const matrix = matrixNoLadder;

  const assets = ['Stocks', 'Bonds', 'REITs'];
  const accounts = ['Traditional', 'Roth', 'Taxable'];
  const assetDollars = { Stocks: pv * stockPct, Bonds: pv * bondPct, REITs: pv * reitPct };
  const acctCapacity = { Traditional: pv * tradPct, Roth: pv * rothPct, Taxable: pv * taxablePct };

  function optimalPlacement(mat) {
    const optAcct = {};
    assets.forEach(a => { optAcct[a] = accounts.slice().sort((x, y) => mat[a][y] - mat[a][x])[0]; });
    const entries = assets.map(a => {
      const order = accounts.slice().sort((x, y) => mat[a][y] - mat[a][x]);
      return { asset: a, dollars: assetDollars[a], preferredOrder: order, spread: mat[a][order[0]] - mat[a][order[2]] };
    }).sort((x, y) => y.spread - x.spread);
    const remaining = { ...acctCapacity };
    const allocs = [];
    for (const e of entries) {
      let left = e.dollars;
      for (const acct of e.preferredOrder) {
        if (left <= 0) break;
        const fit = Math.min(left, remaining[acct]);
        if (fit > 0) { allocs.push({ asset: e.asset, account: acct, dollars: fit }); remaining[acct] -= fit; left -= fit; }
      }
    }
    let total = 0;
    allocs.forEach(a => { total += a.dollars * mat[a.asset][a.account]; });
    return { optAcct, allocs, total };
  }
  const noLadder = optimalPlacement(matrixNoLadder);
  const withLadder = optimalPlacement(matrixLadder);
  const optimalAccount = noLadder.optAcct;
  const allocations = noLadder.allocs;
  let optimalTotal = noLadder.total;

  // Naive: each asset distributed proportional to account capacity (uses no-ladder matrix).
  let naiveTotal = 0;
  assets.forEach(a => {
    const perDollar = tradPct * matrix[a].Traditional + rothPct * matrix[a].Roth + taxablePct * matrix[a].Taxable;
    naiveTotal += assetDollars[a] * perDollar;
  });

  // Worst (anti-optimal): flip preferred order
  const worstEntries = assets.map(a => {
    const accountsByPref = accounts.slice().sort((x, y) => matrix[a][x] - matrix[a][y]); // worst first
    return { asset: a, dollars: assetDollars[a], preferredOrder: accountsByPref };
  });
  const remWorst = { ...acctCapacity };
  let worstTotal = 0;
  for (const e of worstEntries) {
    let dollarsLeft = e.dollars;
    for (const acct of e.preferredOrder) {
      if (dollarsLeft <= 0) break;
      const fit = Math.min(dollarsLeft, remWorst[acct]);
      if (fit > 0) { worstTotal += fit * matrix[e.asset][acct]; remWorst[acct] -= fit; dollarsLeft -= fit; }
    }
  }

  // Annualized alpha in basis points
  const alphaDollars = optimalTotal - naiveTotal;
  const alphaPctOfPV = (alphaDollars / pv) * 100;
  // Convert terminal pct gain to annualized bps: (optimal/naive)^(1/n) - 1
  const alphaAnnualizedBps = naiveTotal > 0 ? (Math.pow(optimalTotal / naiveTotal, 1 / years) - 1) * 10000 : 0;

  // Build per-$1000 matrix display
  const cellValue = (asset, acct) => fmtMoneyFull(matrix[asset][acct] * 1000);
  const isOptimal = (asset, acct) => optimalAccount[asset] === acct;
  const cellClass = (asset, acct) => isOptimal(asset, acct) ? 'highlight' : '';

  // Build allocation summary
  const allocSummary = allocations
    .filter(a => a.dollars > 0.01)
    .map(a => `${a.asset} → ${a.account}: ${fmtMoneyFull(a.dollars)}`)
    .join('<br>');

  // CL336 — Ladder-regime comparison: show ladder placement + alpha + inversion flag.
  const ladderAllocSummary = withLadder.allocs
    .filter(a => a.dollars > 0.01)
    .map(a => `${a.asset} → ${a.account}: ${fmtMoneyFull(a.dollars)}`)
    .join('<br>');
  const ladderTotal = withLadder.total;
  const ladderAlphaBps = naiveTotal > 0 ? (Math.pow(ladderTotal / naiveTotal, 1 / years) - 1) * 10000 : 0;
  // Detect placement inversion: any asset's optimal account differs between regimes
  const inversions = assets.filter(a => noLadder.optAcct[a] !== withLadder.optAcct[a]);
  const ladderRegimeBlock = `
    <p style="font-size:13px;color:var(--muted);margin:18px 0 6px 0;font-family:var(--font-body);"><strong>With planned Roth conversion ladder (${(ladderRate*100).toFixed(0)}% future rate)</strong> — CL336 integrated regime</p>
    <div style="font-size:14px;line-height:1.7;font-family:var(--font-body);background:var(--surface);padding:12px 14px;border-radius:6px;">${ladderAllocSummary || 'No allocation possible (check inputs).'}</div>
    <table class="calc-table" style="margin-top:10px;">
      <tr><th>Regime</th><th>Optimal terminal value</th><th>Annualized alpha vs naive</th></tr>
      <tr><td>No ladder (future rate ${(futureOrd*100).toFixed(0)}%)</td><td>${fmtMoneyFull(optimalTotal)}</td><td>${alphaAnnualizedBps.toFixed(0)} bps/yr</td></tr>
      <tr class="${ladderTotal > optimalTotal ? 'highlight' : ''}"><td>With ladder (future rate ${(ladderRate*100).toFixed(0)}%)</td><td>${fmtMoneyFull(ladderTotal)}</td><td>${ladderAlphaBps.toFixed(0)} bps/yr</td></tr>
      <tr><td>Delta from executing the ladder</td><td>${fmtMoneyFull(ladderTotal - optimalTotal)}</td><td>${(ladderAlphaBps - alphaAnnualizedBps).toFixed(0)} bps/yr</td></tr>
    </table>
    ${inversions.length > 0
      ? `<span class="calc-result-detail" style="display:block;margin-top:10px;"><strong>Placement inversion under the ladder regime:</strong> ${inversions.map(a => `${a} moves from ${noLadder.optAcct[a]} → ${withLadder.optAcct[a]}`).join('; ')}. This is the integrated-planning premium that the Vanguard Bruno-Bortolotti 2017 research quantifies at 30–80 bps/year on top of naive asset-location alpha — the ladder rewrites the placement, not just the rate. See W2:10.1 + CL331 ladder Plan action for execution.</span>`
      : `<span class="calc-result-detail" style="display:block;margin-top:10px;">Optimal placements are unchanged between regimes at your current rate spread — the ladder execution still produces direct tax-rate-arbitrage value (the delta dollar figure above), but doesn't invert the accumulation-phase placement. This is the typical pattern when your ladder rate and no-ladder rate are close; at wider spreads (e.g., 32% peak / 12% with-ladder), placement inversion becomes more likely.</span>`
    }
  `;

  document.getElementById('al-result').innerHTML = `
    ${validationNote ? `<span class="calc-result-detail">${validationNote}</span>` : ''}
    <span class="calc-result-headline">${alphaAnnualizedBps.toFixed(0)} bps/year alpha</span>
    <span class="calc-result-detail">Optimal placement beats naive proportional placement by ${fmtMoneyFull(alphaDollars)} (${alphaPctOfPV.toFixed(1)}% of starting portfolio) over ${years} years.</span>
    <p style="font-size:13px;color:var(--muted);margin:14px 0 6px 0;font-family:var(--font-body);"><strong>Terminal value per $1,000 invested</strong> (★ = optimal placement for that asset)</p>
    <table class="calc-table">
      <tr><th>Asset</th><th>Traditional</th><th>Roth</th><th>Taxable</th></tr>
      <tr><td>Stocks</td><td class="${cellClass('Stocks','Traditional')}">${cellValue('Stocks','Traditional')}${isOptimal('Stocks','Traditional')?' ★':''}</td><td class="${cellClass('Stocks','Roth')}">${cellValue('Stocks','Roth')}${isOptimal('Stocks','Roth')?' ★':''}</td><td class="${cellClass('Stocks','Taxable')}">${cellValue('Stocks','Taxable')}${isOptimal('Stocks','Taxable')?' ★':''}</td></tr>
      <tr><td>Bonds</td><td class="${cellClass('Bonds','Traditional')}">${cellValue('Bonds','Traditional')}${isOptimal('Bonds','Traditional')?' ★':''}</td><td class="${cellClass('Bonds','Roth')}">${cellValue('Bonds','Roth')}${isOptimal('Bonds','Roth')?' ★':''}</td><td class="${cellClass('Bonds','Taxable')}">${cellValue('Bonds','Taxable')}${isOptimal('Bonds','Taxable')?' ★':''}</td></tr>
      <tr><td>REITs</td><td class="${cellClass('REITs','Traditional')}">${cellValue('REITs','Traditional')}${isOptimal('REITs','Traditional')?' ★':''}</td><td class="${cellClass('REITs','Roth')}">${cellValue('REITs','Roth')}${isOptimal('REITs','Roth')?' ★':''}</td><td class="${cellClass('REITs','Taxable')}">${cellValue('REITs','Taxable')}${isOptimal('REITs','Taxable')?' ★':''}</td></tr>
    </table>
    <p style="font-size:13px;color:var(--muted);margin:14px 0 6px 0;font-family:var(--font-body);"><strong>Optimal allocation</strong> (waterfall, capacity-constrained)</p>
    <div style="font-size:14px;line-height:1.7;font-family:var(--font-body);background:var(--surface);padding:12px 14px;border-radius:6px;">${allocSummary || 'No allocation possible (check inputs).'}</div>
    <table class="calc-table" style="margin-top:14px;">
      <tr><th>Placement strategy</th><th>After-tax terminal value</th></tr>
      <tr class="highlight"><td>Optimal (waterfall)</td><td>${fmtMoneyFull(optimalTotal)}</td></tr>
      <tr><td>Naive (proportional to capacity)</td><td>${fmtMoneyFull(naiveTotal)}</td></tr>
      <tr><td>Worst (anti-optimal)</td><td>${fmtMoneyFull(worstTotal)}</td></tr>
    </table>
    <span class="calc-result-detail" style="display:block;margin-top:10px;">The waterfall optimizer is greedy — it ranks assets by the spread between their best and worst account placement, then allocates the highest-spread asset to its preferred account first. This is near-optimal for the 3×3 case and within ~5 bps/year of globally optimal under realistic parameters. The dollar alpha grows with portfolio size and time horizon; for a $1M portfolio over 30 years, 25 bps/year compounds to roughly $80K-$200K depending on inputs. Vanguard's research range of 20–50 bps/year for typical balanced portfolios falls in this regime. Note: the Roth case for stocks is sensitive to expected return — at lower equity returns, the gap between Roth and Taxable narrows, and Taxable can win for stocks because of the step-up basis at death (not modeled here).</span>
    ${ladderRegimeBlock}
  `;
}

function calcHistoricalCycles() {
  const el = document.getElementById('hc-result');
  if (!el) return;
  const pv = $val('hc-pv', 1000000);
  const wd = $val('hc-wd', 40000);
  const stockAlloc = $val('hc-stock', 70) / 100;
  const horizon = $val('hc-years', 30);
  const strategy = (document.getElementById('hc-strategy') || {}).value || 'fixed';

  // CL370/CL373 — starting-valuation regime, applied to first-10-year stock returns.
  const capeRegime = (document.getElementById('hc-cape') || {}).value || 'typical';
  const capeAdjustment = {
    'very-low': 0.020,
    'low': 0.010,
    'typical': 0.000,
    'high': -0.010,
    'very-high': -0.020,
  }[capeRegime] || 0;

  // CL329 — Guaranteed-income overlay inputs.
  const curAge = $val('hc-curage', 65);
  const ss1Pia = $val('hc-ss1', 0);
  // Number.isFinite guard prevents silent NaN flow → SSA_CLAIM_AGE_FACTOR[NaN]
  // || 1.0 = wrong-by-19% benefit projection. Falls back to FRA on bad input.
  const _ss1Raw = parseInt((document.getElementById('hc-ss1-age') || {}).value, 10);
  const ss1ClaimAge = Number.isFinite(_ss1Raw) ? _ss1Raw : 67;
  const ss2Pia = $val('hc-ss2', 0);
  const _ss2Raw = parseInt((document.getElementById('hc-ss2-age') || {}).value, 10);
  const ss2ClaimAge = Number.isFinite(_ss2Raw) ? _ss2Raw : 67;
  const spouseAge = $val('hc-spouse-age', curAge);
  const pensionAnnual = $val('hc-pension', 0);
  const pensionStartAge = $val('hc-pension-age', 65);

  if (pv <= 0 || wd <= 0 || horizon < 10) {
    el.innerHTML = '<span class="calc-result-detail">Inputs must be positive; horizon must be at least 10 years.</span>';
    return;
  }

  // Build streams[] of { annualReal, startYearOffset }.
  const streams = [];
  if (ss1Pia > 0) {
    const benefit = ssaAdjustedBenefit(ss1Pia, ss1ClaimAge);
    const offset = Math.max(0, ss1ClaimAge - curAge);
    streams.push({ annualReal: benefit, startYearOffset: offset });
  }
  if (ss2Pia > 0) {
    const benefit = ssaAdjustedBenefit(ss2Pia, ss2ClaimAge);
    const offset = Math.max(0, ss2ClaimAge - spouseAge);
    streams.push({ annualReal: benefit, startYearOffset: offset });
  }
  if (pensionAnnual > 0) {
    const offset = Math.max(0, pensionStartAge - curAge);
    streams.push({ annualReal: pensionAnnual, startYearOffset: offset });
  }
  const overlayActive = streams.length > 0;
  const totalLifetimeGuaranteed = streams.reduce((sum, s) => sum + s.annualReal * Math.max(0, horizon - s.startYearOffset), 0);

  const backend = getMCBackend();
  const result = backend.simulate({
    pv, annualWithdrawal: wd, stockAlloc, horizonYears: horizon, strategy, streams, capeAdjustment
  });

  if (result.note) {
    el.innerHTML = `<span class="calc-result-detail">${result.note}.</span>`;
    return;
  }

  const successPct = (result.successRate * 100).toFixed(1);
  const failureList = result.failures.length
    ? `<br>Failed cohorts: ${result.failures.join(', ')}.`
    : '<br>All historical cohorts survived this strategy.';

  const stratLabel = strategy === 'fixed' ? 'Bengen (1994) fixed real' : strategy === 'flexible' ? 'Vanguard-style dynamic (cut 25% after down years)' : 'Guyton-Klinger (2006) guardrails';

  // CL329 — overlay summary explaining what was modeled.
  const overlaySummary = overlayActive
    ? `<span class="calc-result-detail" style="display:block;margin-top:10px;"><strong>Guaranteed-income overlay applied:</strong> ${streams.map((s, i) => {
        const labels = ['primary SS', 'spouse SS', 'pension/SPIA/QLAC'];
        return `${labels[i] || 'stream'} ${fmtMoneyFull(s.annualReal)}/yr starting year ${s.startYearOffset}`;
      }).join('; ')}. Across the ${horizon}-year horizon this overlay contributes roughly ${fmtMoneyFull(totalLifetimeGuaranteed)} of real-dollar income that the portfolio doesn't have to fund — connecting back to Math §7's Pfau-Kitces "Social Security bridge" framing where drawing more heavily on the portfolio in early retirement to delay claiming is one of the most-replicated decumulation findings of the last decade.</span>`
    : `<span class="calc-result-detail" style="display:block;margin-top:10px;"><em>No guaranteed-income overlay applied</em> — the success rate above is portfolio-only. For any household reaching FRA, Social Security typically funds 25–60% of essential spending; modeling it materially changes the success rate. Add your PIA and claiming age above to see the household-level picture.</span>`;
  // CL370/CL373 — CAPE regime summary.
  const capeNote = capeRegime !== 'typical'
    ? `<span class="calc-result-detail" style="display:block;margin-top:10px;"><strong>Starting-valuation regime applied:</strong> "${capeRegime}" → ${(capeAdjustment * 100).toFixed(1)}pp shift applied to first 10 years of stock returns in each cohort, approximating the Pfau 2012 valuation-conditional SWR effect. The unconditional historical 4% result is the median-CAPE figure; at very-high CAPE (current US 2026 regime), the conditional historical SWR drops toward 3.0–3.5%. Toggle the regime to "typical" to see the unconditional result for comparison.</span>`
    : '';

  el.innerHTML = `
    <span class="calc-result-headline">${successPct}% historical success rate</span>
    <span class="calc-result-detail">Across ${result.totalCycles} rolling ${horizon}-year cohorts (start years ${HIST_RETURNS[0][0]}–${HIST_RETURNS[HIST_RETURNS.length-horizon][0]}), strategy: <strong>${stratLabel}</strong>${overlayActive ? ', with guaranteed-income overlay' : ''}.${failureList}</span>
    <table class="calc-table" style="margin-top:14px;">
      <tr><th>Percentile of ending portfolio balance (real $)</th><th>Value</th></tr>
      <tr><td>10th — worst quintile</td><td>${fmtMoneyFull(result.percentiles.p10)}</td></tr>
      <tr><td>25th</td><td>${fmtMoneyFull(result.percentiles.p25)}</td></tr>
      <tr class="highlight"><td>50th — median outcome</td><td>${fmtMoneyFull(result.percentiles.p50)}</td></tr>
      <tr><td>75th</td><td>${fmtMoneyFull(result.percentiles.p75)}</td></tr>
      <tr><td>90th — best quintile</td><td>${fmtMoneyFull(result.percentiles.p90)}</td></tr>
    </table>
    ${overlaySummary}
    ${capeNote}
    <span class="calc-result-detail" style="display:block;margin-top:10px;">A 95%+ success rate is the conventional threshold for "safe" — below that, failure cohorts deserve attention. The median ending balance often substantially exceeds starting portfolio (real terms), which is the upside skew that drives the "die with substantial wealth" critique that Die With Zero engages with (see Phase 5 §5). Use percentile spread as the indicator of risk: a tight spread means historical outcomes converged; a wide spread means your plan's outcome depends materially on what kind of cycle you actually encounter.</span>
  `;
  // Fan chart (CL161) — only renders if backend provides per-year paths.
  if (result.paths && result.paths.length) {
    renderHistoricalFanChart({ paths: result.paths, horizonYears: horizon, pv, containerId: 'hc-chart' });
  } else {
    const chartEl = document.getElementById('hc-chart');
    if (chartEl) chartEl.innerHTML = '';
  }
}

function calcRentVsBuy() {
  const price = $val('rb-price', 500000);
  const down = $val('rb-down', 100000);
  const rate = $val('rb-rate', 6.5) / 100;
  const taxPct = $val('rb-tax', 1.2) / 100;
  const maintPct = $val('rb-maint', 1.0) / 100;
  const rentMonthly = $val('rb-rent', 2800);
  const oppRate = $val('rb-opp', 6) / 100;
  const years = $val('rb-years', 7);

  // Mortgage P&I: monthly payment formula
  const loan = price - down;
  const rMonthly = rate / 12;
  const n = years * 12;
  // P&I monthly
  const pi = rMonthly === 0 ? loan / n : loan * rMonthly * Math.pow(1 + rMonthly, n) / (Math.pow(1 + rMonthly, n) - 1);
  // Note: we compute over `years`, but mortgage is typically 30y. For comparison, use the actual 30y P&I and compute totals over the years horizon
  const n30 = 360;
  const pi30 = rMonthly === 0 ? loan / n30 : loan * rMonthly * Math.pow(1 + rMonthly, n30) / (Math.pow(1 + rMonthly, n30) - 1);
  const monthlyPI = pi30;

  // Total owning cost over the horizon
  const totalPI = monthlyPI * 12 * years;
  // Estimate interest portion (approximate, since principal pays down)
  // Use amortization: remaining balance after years
  let bal = loan;
  let totalInterest = 0;
  for (let i = 0; i < n; i++) {
    const interest = bal * rMonthly;
    const principal = monthlyPI - interest;
    totalInterest += interest;
    bal -= principal;
  }
  const totalPrincipalPaid = totalPI - totalInterest;
  const propertyTax = price * taxPct * years;
  const maintenance = price * maintPct * years;
  const insurance = price * 0.004 * years; // ~0.4% rough estimate
  const oppCost = down * (Math.pow(1 + oppRate, years) - 1); // foregone investment growth on down payment

  // Transaction costs (Phase 3 P3A #4 fix)
  // ~3% buying closing costs (origination, title, inspection, transfer) one-time at purchase
  // ~7% selling costs (6% commission + 1% closing) one-time at sale
  const buyingCosts = price * 0.03;
  // 1% real appreciation (long-run US Case-Shiller average; updated from 2% per P3A #3)
  const saleValue = price * Math.pow(1.01, years);
  const sellingCosts = saleValue * 0.07;
  const appreciation = saleValue - price;
  const equityBuilt = totalPrincipalPaid + appreciation;

  const totalOwningCost = totalPI + propertyTax + maintenance + insurance + oppCost + buyingCosts + sellingCosts - equityBuilt;

  // Total renting cost over the horizon: rent + investment growth on (down + monthly savings vs owning)
  const monthlyOwningOutOfPocket = monthlyPI + (price * taxPct / 12) + (price * maintPct / 12) + (price * 0.004 / 12);
  const monthlyRentSavings = Math.max(0, monthlyOwningOutOfPocket - rentMonthly);
  // Invested savings grow each month
  let invested = down; // down payment alternative use
  for (let m = 0; m < years * 12; m++) {
    invested = invested * (1 + oppRate / 12) + monthlyRentSavings;
  }
  const totalRentPaid = rentMonthly * 12 * years * Math.pow(1.03, years / 2); // rough rent escalation midpoint
  const netRentingCost = totalRentPaid - (invested - down);

  const verdict = totalOwningCost < netRentingCost ? 'Buying' : 'Renting';
  const gap = Math.abs(totalOwningCost - netRentingCost);

  document.getElementById('rb-result').innerHTML = `
    <table class="calc-table">
      <tr><th>Scenario</th><th>${years}-year net cost</th></tr>
      <tr class="${verdict==='Buying'?'highlight':''}"><td>Buying (TCO − equity)</td><td>${fmtMoneyFull(totalOwningCost)}</td></tr>
      <tr class="${verdict==='Renting'?'highlight':''}"><td>Renting (rent − investment gains on down payment)</td><td>${fmtMoneyFull(netRentingCost)}</td></tr>
      <tr><td>Difference</td><td>${fmtMoneyFull(gap)} (${verdict} wins)</td></tr>
    </table>
    <span class="calc-result-detail" style="display:block;margin-top:10px;">Owning cost includes P&amp;I, property tax, maintenance, insurance, opportunity cost on down payment, <em>3% buying closing costs, 7% selling costs at end of holding</em>, minus principal paid and 1% annual real appreciation (long-run US Case-Shiller average — HCOL coastal metros run higher, much of the country runs flat or lower). Renting cost includes rent (escalated at ~3%/yr midpoint) minus investment gains on the equivalent of the down payment plus monthly cash flow advantage. Transaction costs are the single biggest source of error in DIY rent-vs-buy comparisons; they're now included. Results are still deterministic — actual outcomes vary widely with appreciation realization (range −5% to +15% annually), rent regime, and maintenance shocks.</span>
  `;
}

function calcVehicleTCO() {
  const aPrice = $val('tco-a-price', 40000);
  const aOp = $val('tco-a-op', 6000);
  const bPrice = $val('tco-b-price', 20000);
  const bOp = $val('tco-b-op', 4500);
  const years = $val('tco-years', 10);
  const rate = $val('tco-rate', 6) / 100;

  // Total cost ignoring resale: purchase + (annual op × years)
  // Apply rough depreciation: assume 50% residual after 10 years for both (simplistic)
  const aResidual = aPrice * 0.20;
  const bResidual = bPrice * 0.20;
  const aTCO = aPrice - aResidual + aOp * years;
  const bTCO = bPrice - bResidual + bOp * years;
  const annualSavings = (aTCO - bTCO) / years;
  // Invest the difference
  const invested = rate === 0 ? annualSavings * years : annualSavings * (Math.pow(1 + rate, years) - 1) / rate;
  const totalAdvantage = bTCO < aTCO ? (aTCO - bTCO) + invested - annualSavings * years : 0;

  const winner = bTCO < aTCO ? 'Vehicle B' : 'Vehicle A';
  const gap = Math.abs(aTCO - bTCO);

  document.getElementById('tco-result').innerHTML = `
    <table class="calc-table">
      <tr><th>Vehicle</th><th>${years}-year TCO</th></tr>
      <tr class="${winner==='Vehicle A'?'highlight':''}"><td>Vehicle A</td><td>${fmtMoneyFull(aTCO)}</td></tr>
      <tr class="${winner==='Vehicle B'?'highlight':''}"><td>Vehicle B</td><td>${fmtMoneyFull(bTCO)}</td></tr>
      <tr><td>Difference</td><td>${fmtMoneyFull(gap)}</td></tr>
      <tr><td>If TCO savings invested at ${(rate*100).toFixed(1)}%</td><td>${fmtMoneyFull(invested)}</td></tr>
    </table>
    <span class="calc-result-detail" style="display:block;margin-top:10px;">TCO = (purchase price − estimated residual at 20%) + (annual operating cost × years). Operating cost should include insurance, fuel/electricity, maintenance, repairs, registration, and parking. The "invested" row shows the compounded value of the annual difference if redirected to investments — the real long-term opportunity cost of the more expensive vehicle.</span>
  `;
}

function calcHDHPvsPPO() {
  const hdhpPrem = $val('hp-hdhp-prem', 2400);
  const hdhpDed = $val('hp-hdhp-ded', 3000);
  const hdhpOOP = $val('hp-hdhp-oop', 7500);
  const ppoPrem = $val('hp-ppo-prem', 4800);
  const ppoDed = $val('hp-ppo-ded', 1000);
  const ppoOOP = $val('hp-ppo-oop', 5000);
  const spend = $val('hp-spend', 2500);
  const hsa = $val('hp-hsa', 4400);
  const tax = $val('hp-tax', 24) / 100;

  // Simplified: assume 20% coinsurance after deductible until OOP max
  function planCost(prem, ded, oop, spending) {
    if (spending <= ded) return prem + spending;
    const afterDed = spending - ded;
    const coinsurance = Math.min(afterDed * 0.20, oop - ded);
    const total = prem + ded + coinsurance;
    return Math.min(total, prem + oop);
  }

  const hdhpCost = planCost(hdhpPrem, hdhpDed, hdhpOOP, spend);
  const ppoCost = planCost(ppoPrem, ppoDed, ppoOOP, spend);
  const hsaSavings = hsa * tax; // tax savings on HSA contributions
  const hdhpNet = hdhpCost - hsaSavings;
  const winner = hdhpNet < ppoCost ? 'HDHP + HSA' : 'PPO';
  const gap = Math.abs(hdhpNet - ppoCost);

  // CL391 — HDHP liquidity gate. Surface a warning when the household's
  // diagnostic emergency-fund value is below the displayed deductible + OOP.
  // HDHP advice that's correct on cost math is harmful when the household
  // can't absorb the deductible from cash and ends up funding it on 24%+ APR.
  const liquidityHint = (() => {
    const efAnswer = (state.answers || {}).emergencyFund;
    // Map diagnostic bucket to a rough liquid-cash floor estimate; the household
    // really only needs deductible + OOP, so we compare against the plan's annual
    // exposure rather than expenses-based EF math.
    // Diagnostic options: '0' / '<1mo' / '1-3mo' / '3-6mo' / '6-12mo' / '12+mo'.
    // We treat 0 and <1mo as "insufficient for HDHP" regardless of expenses;
    // 1-3mo as "borderline" if HDHP exposure > $5K; 3-6mo+ as "sufficient" for
    // the typical-household case.
    if (!efAnswer) return '';
    const hdhpExposure = hdhpDed + (hdhpOOP - hdhpDed); // total worst-case OOP
    if (efAnswer === '0' || efAnswer === '<1mo') {
      return `<div class="calc-warning"><strong>Liquidity gate triggered.</strong> Your Diagnostic answer indicates an emergency fund below one month of essentials. The HDHP's worst-case out-of-pocket exposure here is ${fmtMoneyFull(hdhpExposure)}, which means a single ER visit or unexpected procedure routes to credit-card debt at 24%+ APR. The PPO is the safer choice this year even if the headline math above shows HDHP winning — build the cash floor first, then revisit at next open enrollment. See the "HDHP precondition — the liquidity gate" callout above for the underlying argument.</div>`;
    }
    if (efAnswer === '1-3mo' && hdhpExposure > 5000) {
      return `<div class="calc-warning"><strong>Liquidity gate — borderline.</strong> Your emergency fund (1–3 months of essentials) is close to the line for this HDHP's ${fmtMoneyFull(hdhpExposure)} worst-case exposure. The HDHP+HSA math wins on average expected cost; the risk is the tail-event year where the deductible has to be funded from somewhere other than cash. If your liquid savings are toward the lower end of this band, the PPO is the more defensive choice for this year.</div>`;
    }
    return '';
  })();

  document.getElementById('hp-result').innerHTML = `
    <table class="calc-table">
      <tr><th>Plan</th><th>Annual cost</th></tr>
      <tr class="${winner==='HDHP + HSA'?'highlight':''}"><td>HDHP (premium + OOP − HSA tax savings)</td><td>${fmtMoneyFull(hdhpNet)}</td></tr>
      <tr class="${winner==='PPO'?'highlight':''}"><td>PPO (premium + OOP)</td><td>${fmtMoneyFull(ppoCost)}</td></tr>
      <tr><td>Difference</td><td>${fmtMoneyFull(gap)} (${winner} wins at this spending level)</td></tr>
    </table>
    <span class="calc-result-detail" style="display:block;margin-top:10px;">Coinsurance assumed at 20% after deductible. HSA tax savings = contribution × marginal rate. Long-term: any unused HSA balance compounds tax-free for decades — over 30 years at 6% real return, a $4,400 annual contribution grows to roughly $350,000 in tax-free retirement medical funds. The break-even spending level is where the two plans cost equal; running this calculator at three different expected spending levels (low/moderate/high) reveals which plan dominates across the range you actually face.</span>
    ${liquidityHint}
  `;
}

function calcDIME() {
  const debt = $val('dime-debt', 20000);
  const income = $val('dime-income', 80000);
  const years = $val('dime-years', 20);
  const mortgage = $val('dime-mortgage', 400000);
  const edu = $val('dime-edu', 250000);

  const incomeReplacement = income * years;
  const total = debt + incomeReplacement + mortgage + edu;
  const rounded = Math.ceil(total / 250000) * 250000; // round up to nearest $250K

  document.getElementById('dime-result').innerHTML = `
    <span class="calc-result-headline">${fmtMoneyFull(rounded)}</span>
    <span class="calc-result-detail">Recommended term life coverage (rounded up to nearest $250K policy increment). Breakdown: Debt ${fmtMoneyFull(debt)} + Income replacement ${fmtMoneyFull(incomeReplacement)} (${income.toLocaleString()} × ${years} yr) + Mortgage ${fmtMoneyFull(mortgage)} + Education ${fmtMoneyFull(edu)} = ${fmtMoneyFull(total)}. Choose term length to match the duration of need — most people use a 20 or 30-year level term to cover working years and child-rearing. Avoid whole life as an investment vehicle; the returns are typically 3–5% gross, much less net of fees.</span>
  `;
}

function calcDI() {
  const monthlyIncome = $val('di-income', 10000);
  const groupCap = $val('di-group-cap', 10000);
  const groupTaxable = ((document.getElementById('di-group-taxable') || {}).value || 'yes') === 'yes';
  const targetRate = $val('di-target', 65) / 100;
  const taxRate = $val('di-tax', 32) / 100;
  const years = $val('di-years', 20);

  // Tax-equivalent group benefit: if employer-paid (taxable), divide by (1-tax) to compare with after-tax target.
  // Standard analysis works in pre-tax (gross) dollar terms.
  const groupAfterTax = groupTaxable ? groupCap * (1 - taxRate) : groupCap;
  const targetMonthly = monthlyIncome * targetRate;
  const gapMonthly = Math.max(0, targetMonthly - groupAfterTax);
  const gapAnnual = gapMonthly * 12;
  // PV of gap at 3% real discount over years
  const r = 0.03;
  const pvFactor = r === 0 ? years : (1 - Math.pow(1 + r, -years)) / r;
  const gapPV = gapAnnual * pvFactor;

  let posture;
  if (gapMonthly < 500) {
    posture = '<strong>Coverage is approximately adequate.</strong> Your group LTD' + (groupTaxable ? ' (after taxes on the benefit)' : '') + ' is close to your target replacement rate; the marginal value of additional individual own-occupation coverage is bounded. Verify your group policy is <em>own-occupation</em> rather than "any-occupation" (the any-occ definition is much narrower and frequently denies legitimate claims for skilled workers).';
  } else if (gapMonthly < 2500) {
    posture = '<strong>Modest gap.</strong> Consider an individual own-occupation DI supplement for the gap. For your income level, pricing typically runs $40–$120/month for $' + Math.round(gapMonthly/100)*100 + '/mo of additional own-occ coverage from a top carrier (Guardian, Principal, MassMutual, Standard) — verifiable in 15 minutes via a broker quote. Lock pricing in while you\'re healthy; underwriting tightens with each diagnosis.';
  } else {
    posture = '<strong>Substantial gap — close it before adding term life.</strong> Your group LTD' + (groupTaxable ? ' (after taxes on the benefit)' : '') + ' replaces a fraction of your target. At your income, the unreplaced gap PV typically exceeds $1M and the lifetime probability of a 90+ day disability before age 65 is approximately 25% per Council for Disability Awareness data. Get an individual own-occupation DI supplement from a top carrier (Guardian, Principal, MassMutual, Standard) with a 90-day elimination period and benefits to age 65 or 67. Pricing typically runs 1–3% of income for this level of coverage. <em>The DI-vs-life priority inversion at high income (CL335 Plan action) treats this as a "next-quarter / critical" item — DI gap PV typically exceeds the additional term-life need.</em>';
  }

  document.getElementById('di-result').innerHTML = `
    <span class="calc-result-headline">${fmtMoneyFull(gapMonthly)}/mo gap</span>
    <span class="calc-result-detail">Target replacement: ${fmtMoneyFull(targetMonthly)}/mo (${(targetRate*100).toFixed(0)}% of ${fmtMoneyFull(monthlyIncome)}/mo gross). Group LTD effective benefit (${groupTaxable ? 'after tax' : 'tax-free'}): ${fmtMoneyFull(groupAfterTax)}/mo. <strong>Gap: ${fmtMoneyFull(gapMonthly)}/mo</strong>, annualized ${fmtMoneyFull(gapAnnual)}, PV over ${years}yr at 3% real discount: ${fmtMoneyFull(gapPV)}.</span>
    <span class="calc-result-detail" style="display:block;margin-top:10px;">${posture}</span>
  `;
}

function calcDCFSA() {
  const amount = $val('dc-amount', 5000);
  const fed = $val('dc-fed', 24) / 100;
  const state = $val('dc-state', 5) / 100;
  const fica = $val('dc-fica', 7.65) / 100;
  const totalRate = fed + state + fica;
  const savings = amount * totalRate;
  document.getElementById('dc-result').innerHTML = `
    <span class="calc-result-headline">${fmtMoneyFull(savings)}</span>
    <span class="calc-result-detail">Annual tax savings from a fully-funded DCFSA at your combined marginal rate of ${(totalRate * 100).toFixed(1)}%. The DCFSA effectively converts $${amount.toLocaleString()} of childcare cost from after-tax to pre-tax dollars. Note: 2026 limit is $5,000 per household regardless of filing status (not per parent). The Child and Dependent Care Tax Credit is also available but phases down at higher incomes — high earners should use DCFSA exclusively.</span>
  `;
}

function calcSubscription() {
  const monthly = $val('sub-monthly', 15);
  const years = $val('sub-years', 20);
  const rate = $val('sub-rate', 6) / 100;
  const annual = monthly * 12;
  const totalNominal = annual * years;
  // FV of annuity
  const rMonthly = rate / 12;
  const n = years * 12;
  const fv = rMonthly === 0 ? monthly * n : monthly * (Math.pow(1 + rMonthly, n) - 1) / rMonthly;
  document.getElementById('sub-result').innerHTML = `
    <span class="calc-result-headline">${fmtMoneyFull(fv)}</span>
    <span class="calc-result-detail">If you redirected this $${monthly}/month subscription into investments at ${(rate * 100).toFixed(1)}% real return for ${years} years, it would compound to ${fmtMoneyFull(fv)}. Direct outlay over the same period: ${fmtMoneyFull(totalNominal)}. The opportunity cost (foregone growth) is ${fmtMoneyFull(fv - totalNominal)} — the part of the subscription's true cost that monthly billing hides.</span>
  `;
}

function calcLifestyleCreep() {
  const income = $val('lc-income', 120000);
  const sr = $val('lc-rate', 25) / 100;
  const creep = $val('lc-creep', 400);
  const r = $val('lc-return', 5) / 100;
  const wr = 0.04;
  const k = 1 / wr;
  // Current savings rate → years to FI
  const yearsCurrent = Math.log(1 + k * r * (1 - sr) / sr) / Math.log(1 + r);
  // After creep: spending up by creep*12, savings down by same
  const annualCreep = creep * 12;
  const newSavings = (income * sr) - annualCreep;
  const newSpending = income - newSavings;
  const newSR = newSavings / income;
  if (newSR <= 0 || newSR >= 1) {
    document.getElementById('lc-result').innerHTML = `<span class="calc-result-detail">The proposed lifestyle creep exceeds your current savings. Try a smaller monthly creep amount.</span>`;
    return;
  }
  const yearsAfterCreep = Math.log(1 + k * r * (1 - newSR) / newSR) / Math.log(1 + r);
  const delta = yearsAfterCreep - yearsCurrent;
  document.getElementById('lc-result').innerHTML = `
    <table class="calc-table">
      <tr><th>Scenario</th><th>Savings rate</th><th>Years to FI</th></tr>
      <tr class="highlight"><td>Current</td><td>${(sr * 100).toFixed(1)}%</td><td>${yearsCurrent.toFixed(1)} yr</td></tr>
      <tr><td>After $${creep}/mo lifestyle creep</td><td>${(newSR * 100).toFixed(1)}%</td><td>${yearsAfterCreep.toFixed(1)} yr</td></tr>
      <tr><td>Delay</td><td>−${((sr - newSR) * 100).toFixed(1)} pp</td><td>+${delta.toFixed(1)} yr</td></tr>
    </table>
    <span class="calc-result-detail" style="display:block;margin-top:10px;">An additional $${creep}/month in spending ($${annualCreep.toLocaleString()}/yr) reduces your savings rate by ${((sr - newSR) * 100).toFixed(1)} percentage points and adds ${delta.toFixed(1)} years to financial independence. This is the deterministic version — actual delay also depends on whether the creep is one-time or recurring with future raises. Assumes constant income and the standard MMM savings rate formula from Phase 2 §3.</span>
  `;
}

function calcExpenseRatio() {
  const pv = $val('er-pv', 100000);
  const pmt = $val('er-pmt', 20000);
  const years = $val('er-years', 30);
  const gross = $val('er-gross', 7) / 100;
  const lowER = $val('er-low', 0.05) / 100;
  const highER = $val('er-high', 1.00) / 100;
  const netLow = gross - lowER;
  const netHigh = gross - highER;

  // Annual contributions, compounded
  function fv(r, pv, pmt, n) {
    return pv * Math.pow(1 + r, n) + (r === 0 ? pmt * n : pmt * (Math.pow(1 + r, n) - 1) / r);
  }
  const fvLow = fv(netLow, pv, pmt, years);
  const fvHigh = fv(netHigh, pv, pmt, years);
  const drag = fvLow - fvHigh;
  const dragPct = (drag / fvLow) * 100;
  document.getElementById('er-result').innerHTML = `
    <table class="calc-table">
      <tr><th>Expense ratio</th><th>Ending balance</th></tr>
      <tr class="highlight"><td>${(lowER*100).toFixed(2)}% (low-cost index)</td><td>${fmtMoneyFull(fvLow)}</td></tr>
      <tr><td>${(highER*100).toFixed(2)}% (typical active fund)</td><td>${fmtMoneyFull(fvHigh)}</td></tr>
      <tr><td>Cost of higher expense ratio</td><td>${fmtMoneyFull(drag)} (${dragPct.toFixed(1)}% of low-cost outcome)</td></tr>
    </table>
    <span class="calc-result-detail" style="display:block;margin-top:10px;">The expense ratio differential is compounded against gross returns annually. Over long horizons, even small percentage point differences become large absolute dollar amounts. This is the structural reason index funds win the empirical argument — the gross return alpha required to overcome a 95-bp fee differential ex-ante is implausibly high. Calculator uses annual compounding with end-of-period contributions; deterministic projection without volatility (see Math §1 disclaimer).</span>
  `;
}

function calcEfficientFrontier() {
  const sret = $val('ef-sret', 7) / 100;
  const svol = $val('ef-svol', 16) / 100;
  const bret = $val('ef-bret', 3) / 100;
  const bvol = $val('ef-bvol', 5) / 100;
  const corr = $val('ef-corr', 0.1);
  const wS = $val('ef-alloc', 70) / 100;
  const wB = 1 - wS;

  // Portfolio expected return and variance
  const pRet = wS * sret + wB * bret;
  const pVar = wS*wS*svol*svol + wB*wB*bvol*bvol + 2*wS*wB*corr*svol*bvol;
  const pVol = Math.sqrt(pVar);

  // Find minimum-variance portfolio (closed form for two assets)
  // w_min = (σ_b² - ρσ_sσ_b) / (σ_s² + σ_b² - 2ρσ_sσ_b)
  const numerator = bvol*bvol - corr*svol*bvol;
  const denominator = svol*svol + bvol*bvol - 2*corr*svol*bvol;
  const wSMin = denominator > 0 ? numerator / denominator : 0;
  const minVar = wSMin*wSMin*svol*svol + (1-wSMin)*(1-wSMin)*bvol*bvol + 2*wSMin*(1-wSMin)*corr*svol*bvol;
  const minVol = Math.sqrt(minVar);
  const minRet = wSMin * sret + (1-wSMin) * bret;

  document.getElementById('ef-result').innerHTML = `
    <table class="calc-table">
      <tr><th>Portfolio</th><th>Expected return</th><th>Volatility</th></tr>
      <tr class="highlight"><td>Your allocation (${(wS*100).toFixed(0)}/${(wB*100).toFixed(0)})</td><td>${(pRet*100).toFixed(2)}%</td><td>${(pVol*100).toFixed(2)}%</td></tr>
      <tr><td>Minimum variance (${(wSMin*100).toFixed(0)}/${((1-wSMin)*100).toFixed(0)})</td><td>${(minRet*100).toFixed(2)}%</td><td>${(minVol*100).toFixed(2)}%</td></tr>
      <tr><td>100% stocks</td><td>${(sret*100).toFixed(2)}%</td><td>${(svol*100).toFixed(2)}%</td></tr>
      <tr><td>100% bonds</td><td>${(bret*100).toFixed(2)}%</td><td>${(bvol*100).toFixed(2)}%</td></tr>
    </table>
    <span class="calc-result-detail" style="display:block;margin-top:10px;">Two-asset MPT with portfolio variance σ² = w<sub>s</sub>²σ<sub>s</sub>² + w<sub>b</sub>²σ<sub>b</sub>² + 2w<sub>s</sub>w<sub>b</sub>ρσ<sub>s</sub>σ<sub>b</sub>. The minimum-variance portfolio is typically more bond-heavy than most investors hold; portfolios to the right (more equity) accept additional risk for additional expected return. The efficient frontier in this two-asset case is the curve traced by varying w<sub>s</sub> from 0 to 1 (or above 1 with leverage). Note: real-world expected returns and volatilities are notoriously hard to estimate; small input changes produce large allocation changes — the framework's pedagogical value exceeds its operational precision.</span>
  `;
}

function calcSharpe() {
  const aRet = $val('sh-aret', 9) / 100;
  const aVol = $val('sh-avol', 14) / 100;
  const bRet = $val('sh-bret', 7) / 100;
  const bVol = $val('sh-bvol', 8) / 100;
  const rf = $val('sh-rf', 4) / 100;
  const aSharpe = aVol > 0 ? (aRet - rf) / aVol : 0;
  const bSharpe = bVol > 0 ? (bRet - rf) / bVol : 0;
  const winner = aSharpe > bSharpe ? 'Portfolio A' : (bSharpe > aSharpe ? 'Portfolio B' : 'Tie');
  document.getElementById('sh-result').innerHTML = `
    <table class="calc-table">
      <tr><th>Portfolio</th><th>Excess return</th><th>Vol</th><th>Sharpe ratio</th></tr>
      <tr class="${winner==='Portfolio A'?'highlight':''}"><td>Portfolio A</td><td>${((aRet-rf)*100).toFixed(2)}%</td><td>${(aVol*100).toFixed(2)}%</td><td>${aSharpe.toFixed(3)}</td></tr>
      <tr class="${winner==='Portfolio B'?'highlight':''}"><td>Portfolio B</td><td>${((bRet-rf)*100).toFixed(2)}%</td><td>${(bVol*100).toFixed(2)}%</td><td>${bSharpe.toFixed(3)}</td></tr>
    </table>
    <span class="calc-result-detail" style="display:block;margin-top:10px;">Sharpe ratio = (R<sub>p</sub> − R<sub>f</sub>) / σ<sub>p</sub>. ${winner === 'Tie' ? 'Both portfolios deliver equivalent risk-adjusted returns.' : winner + ' has the higher Sharpe ratio — more excess return per unit of volatility risk.'} The Sharpe ratio compares portfolios on risk-adjusted basis but assumes (a) volatility is the right measure of risk, which is debatable for skewed return distributions, and (b) returns are stationary, which they aren't over short samples. A 0.5 Sharpe is typical for the S&amp;P 500 long-run; 1.0+ is excellent; sustained 2.0+ usually indicates leverage or strategy capacity limits not yet hit. <strong>Caveats worth knowing.</strong> Lo's 2002 paper "The Statistics of Sharpe Ratios" (<em>Financial Analysts Journal</em>) showed that Sharpe ratio confidence intervals are wide for typical sample sizes — a 5-year measurement of 0.7 versus 0.5 is typically not statistically distinguishable; manager rankings based on Sharpe over short windows mostly reflect noise. For skewed return distributions (options strategies, credit, anything with fat left tails), the <em>Sortino ratio</em> (which uses downside deviation rather than total volatility) is often more informative. The <em>Calmar ratio</em> (annualized return / max drawdown) better captures the risk that matters for retirees and leveraged investors. None of these is a complete substitute for understanding the underlying return distribution; all are partial summaries.</span>
  `;
}

function calcCoastFIRE() {
  const pv = $val('coast-pv', 100000);
  const target = $val('coast-target', 1500000);
  const years = $val('coast-years', 35);
  const rate = $val('coast-rate', 6) / 100;
  const annualContrib = $val('coast-contrib', 20000);

  // Will current portfolio reach target with no additional contributions?
  const projectedNoContrib = pv * Math.pow(1 + rate, years);
  const isCoast = projectedNoContrib >= target;
  const shortfall = Math.max(0, target - projectedNoContrib);

  // What balance today would be Coast FIRE?
  const coastNeeded = target / Math.pow(1 + rate, years);
  const ratio = pv / coastNeeded;

  // If not yet, how many more years of contributions at user's specified rate?
  let yearsToCoast = 0;
  let bal = pv;
  if (annualContrib > 0) {
    while (bal * Math.pow(1 + rate, years - yearsToCoast) < target && yearsToCoast < years) {
      bal = bal * (1 + rate) + annualContrib;
      yearsToCoast++;
    }
  } else {
    yearsToCoast = isCoast ? 0 : Infinity;
  }

  document.getElementById('coast-result').innerHTML = isCoast
    ? `<span class="calc-result-headline">✓ You are Coast FIRE</span>
       <span class="calc-result-detail">Your current portfolio of ${fmtMoneyFull(pv)} grows to ${fmtMoneyFull(projectedNoContrib)} by traditional retirement at ${(rate*100).toFixed(1)}% real return — exceeding your ${fmtMoneyFull(target)} target. You no longer need to contribute new money; compound growth alone reaches the goal. Current portfolio is ${ratio.toFixed(2)}× the minimum coast threshold.</span>`
    : `<span class="calc-result-headline">${fmtMoneyFull(shortfall)} short</span>
       <span class="calc-result-detail">Your current portfolio of ${fmtMoneyFull(pv)} would grow to ${fmtMoneyFull(projectedNoContrib)} without contributions — short of your ${fmtMoneyFull(target)} target by ${fmtMoneyFull(shortfall)}. To reach Coast FIRE you need approximately ${fmtMoneyFull(coastNeeded)} invested today (you have ${(ratio*100).toFixed(0)}% of that). ${annualContrib > 0 ? `At $${annualContrib.toLocaleString()}/year additional contributions, you'd hit Coast FIRE in approximately ${yearsToCoast} years.` : `With zero additional contributions, you cannot reach Coast FIRE from current portfolio.`}</span>`;
}

function calcDividend() {
  const pv = $val('div-pv', 1000000);
  const need = $val('div-need', 40000);
  // Strategy A: dividend-focused
  const aYield = $val('div-a-yield', 4) / 100;
  const aApprec = $val('div-a-apprec', 3) / 100;
  const aTotal = aYield + aApprec;
  // Strategy B: total-return-focused
  const bYield = $val('div-b-yield', 1.5) / 100;
  const bApprec = $val('div-b-apprec', 5.5) / 100;
  const bTotal = bYield + bApprec;

  const years = 30;
  const inflation = 0.03;

  function simulate(yieldRate, apprecRate) {
    let bal = pv;
    let withdrawal = need;
    for (let y = 0; y < years; y++) {
      const dividends = bal * yieldRate;
      if (dividends >= withdrawal) {
        // Dividends cover need; reinvest surplus
        bal += (dividends - withdrawal);
      } else {
        // Sell shares for shortfall
        bal -= (withdrawal - dividends);
      }
      if (bal < 0) return { ending: 0, depleted: y + 1 };
      // Capital appreciation on the post-distribution balance
      bal *= 1 + apprecRate;
      withdrawal *= 1 + inflation;
    }
    return { ending: bal, depleted: null };
  }

  const a = simulate(aYield, aApprec);
  const b = simulate(bYield, bApprec);

  const aEnd = a.depleted ? `Depleted yr ${a.depleted}` : fmtMoneyFull(a.ending);
  const bEnd = b.depleted ? `Depleted yr ${b.depleted}` : fmtMoneyFull(b.ending);
  const isEquivalent = Math.abs(aTotal - bTotal) < 0.001;
  const totalDiff = aTotal - bTotal;

  let interpretation = '';
  if (isEquivalent) {
    interpretation = `Both strategies have the same total return (${(aTotal*100).toFixed(2)}%). Miller-Modigliani (1961) shows that at equal pre-tax total returns, dividend strategy and total-return strategy are economically equivalent — the small remaining difference here comes from the interaction of dividend timing with inflation-adjusted withdrawals. The "live off dividends" framing is psychologically different from systematic selling but mathematically equivalent. The real differentiation is in tax treatment (qualified dividends and LTCG are taxed identically in most cases; non-qualified dividends are worse) and behavioral discipline (dividends arrive automatically; systematic selling requires action).`;
  } else if (totalDiff > 0) {
    interpretation = `Dividend-focused strategy has higher total return (${(aTotal*100).toFixed(2)}% vs ${(bTotal*100).toFixed(2)}%) — it wins on math because of the assumed return advantage, not because dividends are inherently better. If you can identify dividend-paying stocks with reliably higher total returns, that's an alpha source, not a dividend-strategy advantage.`;
  } else {
    interpretation = `Total-return-focused strategy has higher total return (${(bTotal*100).toFixed(2)}% vs ${(aTotal*100).toFixed(2)}%) — it wins on math because of the assumed return advantage. The common real-world pattern: yield-chasing produces portfolios with lower total returns, since high-dividend stocks are systematically slower-growing companies. This is the substantive risk in "live off dividends" — not the dividend framing itself, but the selection bias toward lower-total-return holdings.`;
  }

  document.getElementById('div-result').innerHTML = `
    <table class="calc-table">
      <tr><th>Strategy</th><th>Yield</th><th>Appreciation</th><th>Total return</th><th>30-year ending balance</th></tr>
      <tr><td>Dividend-focused</td><td>${(aYield*100).toFixed(2)}%</td><td>${(aApprec*100).toFixed(2)}%</td><td>${(aTotal*100).toFixed(2)}%</td><td>${aEnd}</td></tr>
      <tr><td>Total-return-focused</td><td>${(bYield*100).toFixed(2)}%</td><td>${(bApprec*100).toFixed(2)}%</td><td>${(bTotal*100).toFixed(2)}%</td><td>${bEnd}</td></tr>
    </table>
    <span class="calc-result-detail" style="display:block;margin-top:10px;">${interpretation}</span>
  `;
}

function calcDieWithZero() {
  const income = $val('dz-income', 120000);
  const age = $val('dz-age', 40);
  const retire = $val('dz-retire', 65);
  const life = $val('dz-life', 85);
  const sr = $val('dz-savings', 25) / 100;
  const r = $val('dz-return', 5) / 100;

  if (retire <= age || life <= retire) {
    document.getElementById('dz-result').innerHTML = `<span class="calc-result-detail">Retirement age must exceed current age, and life expectancy must exceed retirement age.</span>`;
    return;
  }

  const yearsWorking = retire - age;
  const yearsRetired = life - retire;
  const annualSavings = income * sr;
  const annualSpending = income - annualSavings;

  // Accumulate to retirement
  const portfolioAtRetire = annualSavings * (r === 0 ? yearsWorking : (Math.pow(1 + r, yearsWorking) - 1) / r);

  // Sustainable withdrawal over retirement: solve for level real withdrawal that depletes portfolio
  // W = P × r / (1 − (1+r)^(-n))
  const sustainableW = yearsRetired === 0 ? portfolioAtRetire
    : portfolioAtRetire * r / (1 - Math.pow(1 + r, -yearsRetired));
  // "Die with zero" gap: retirement spending vs current spending
  const consumptionRatio = sustainableW / annualSpending;
  const terminalUtility = sustainableW * yearsRetired;
  const lifetimeAccum = portfolioAtRetire;

  document.getElementById('dz-result').innerHTML = `
    <table class="calc-table">
      <tr><th>Metric</th><th>Value</th></tr>
      <tr><td>Current annual spending</td><td>${fmtMoneyFull(annualSpending)}</td></tr>
      <tr><td>Portfolio at retirement (age ${retire})</td><td>${fmtMoneyFull(portfolioAtRetire)}</td></tr>
      <tr class="highlight"><td>Sustainable annual spending in retirement (depletes by age ${life})</td><td>${fmtMoneyFull(sustainableW)}</td></tr>
      <tr><td>Retirement-vs-working spending ratio</td><td>${consumptionRatio.toFixed(2)}×</td></tr>
    </table>
    <span class="calc-result-detail" style="display:block;margin-top:10px;">At ${(sr*100).toFixed(0)}% savings rate, you'd accumulate ${fmtMoneyFull(portfolioAtRetire)} by retirement and could sustainably spend ${fmtMoneyFull(sustainableW)} annually through ${life}, depleting the portfolio to zero at end-of-life. The ratio of retirement-to-working spending is ${consumptionRatio.toFixed(2)}× — values above 1.0 suggest you're under-spending now relative to retirement capacity (Die with Zero would suggest spending more now); values below 1.0 suggest your retirement comfort depends on continued accumulation. This is a deterministic point estimate ignoring longevity risk, late-life medical costs, market volatility, and Social Security; Perkins recommends annuitization for longevity insurance. See Math §5 for sequence risk; see Phase 2 §3 for the savings rate framework being modulated here.</span>
  `;
}

function fmtMoneyFull(n) {
  if (!isFinite(n)) return '—';
  return '$' + Math.round(n).toLocaleString();
}

const _debouncedCache = new WeakMap();

function $val(id, def) {
  const el = document.getElementById(id);
  if (!el) return def;
  const v = parseFloat(el.value);
  if (!isFinite(v)) return def;
  // Honor the input's own min/max attributes — browsers don't enforce them
  // for typed/pasted values on number inputs; this does.
  const min = parseFloat(el.getAttribute('min'));
  const max = parseFloat(el.getAttribute('max'));
  if (isFinite(min) && v < min) return min;
  if (isFinite(max) && v > max) return max;
  // Defense-in-depth absolute cap for inputs lacking attrs (e.g., scientific
  // notation like 1e308 that would overflow calculator math).
  if (v > 1e12) return 1e12;
  if (v < -1e12) return -1e12;
  return v;
}

function renderCompoundChart({ pv, pmt, rateAnnual, years, containerId }) {
  const rMonthly = rateAnnual / 12;
  // Sample year indices so we render at most ~30 bars; always include final year.
  const maxBars = 30;
  const stride = Math.max(1, Math.ceil(years / maxBars));
  const yearsToShow = [];
  for (let y = stride; y < years; y += stride) yearsToShow.push(y);
  if (yearsToShow[yearsToShow.length - 1] !== years) yearsToShow.push(years);

  const data = yearsToShow.map(y => {
    const n = y * 12;
    const fvP = pv * Math.pow(1 + rMonthly, n);
    const fvC = rMonthly === 0 ? pmt * n : pmt * (Math.pow(1 + rMonthly, n) - 1) / rMonthly;
    const contributed = pv + pmt * n;
    const total = fvP + fvC;
    const growth = Math.max(0, total - contributed);
    return { year: y, contributed, growth, total };
  });
  const yMax = niceCeil(data[data.length - 1].total);
  const xLabels = data.map(d => String(d.year));
  const F = chartFrame({ title: 'Year-by-year balance: contributions (taupe) + investment growth (gold)', xLabels, yMax });

  const barWidth = (F.PW / data.length) * 0.7;
  let bars = '';
  data.forEach((d, i) => {
    const cx = F.xScale(i);
    const x = cx - barWidth / 2;
    const yTop = F.yScale(d.total);
    const yContribTop = F.yScale(d.contributed);
    const yBase = F.MT + F.PH;
    // contributions (bottom segment, taupe)
    bars += `<rect x="${x}" y="${yContribTop}" width="${barWidth}" height="${yBase - yContribTop}" fill="var(--p-foundation)"/>`;
    // growth (top segment, gold)
    if (d.growth > 0) {
      bars += `<rect x="${x}" y="${yTop}" width="${barWidth}" height="${yContribTop - yTop}" fill="var(--accent)"/>`;
    }
  });

  const legend = `
    <g transform="translate(${F.ML}, ${F.H - 8})">
      <rect x="0" y="-9" width="11" height="11" fill="var(--p-foundation)"/>
      <text class="legend-text" x="16" y="0">Contributions</text>
      <rect x="118" y="-9" width="11" height="11" fill="var(--accent)"/>
      <text class="legend-text" x="134" y="0">Investment growth</text>
    </g>`;
  renderSVG(containerId, F.W, F.H, F.frame + bars + legend);
}

function renderSequenceChart({ badPath, goodPath, pv, containerId }) {
  const n = Math.max(badPath.length, goodPath.length);
  const xLabels = [];
  for (let i = 0; i < n; i++) xLabels.push(String(i));
  const yMax = niceCeil(Math.max(pv, ...badPath, ...goodPath) * 1.05);
  const F = chartFrame({ title: 'Portfolio balance over 30 years (nominal $)', xLabels, yMax, xTickEvery: 5 });

  const toPoints = path => path.map((v, i) => `${F.xScale(i).toFixed(1)},${F.yScale(v).toFixed(1)}`).join(' ');
  // Starting reference line (initial balance)
  const startY = F.yScale(pv);
  const refLine = `<line class="grid-line" x1="${F.ML}" x2="${F.ML + F.PW}" y1="${startY}" y2="${startY}" stroke="var(--muted-soft)" stroke-dasharray="3 4"/>`;
  const refLabel = `<text class="axis-label" x="${F.ML + F.PW - 4}" y="${startY - 4}" text-anchor="end" fill="var(--muted)">Starting balance</text>`;

  const badLine = `<polyline points="${toPoints(badPath)}" fill="none" stroke="var(--p-safety)" stroke-width="2.2" stroke-linejoin="round"/>`;
  const goodLine = `<polyline points="${toPoints(goodPath)}" fill="none" stroke="var(--p-highdebt)" stroke-width="2.2" stroke-linejoin="round"/>`;

  const legend = `
    <g transform="translate(${F.ML}, ${F.H - 8})">
      <line x1="0" x2="22" y1="-4" y2="-4" stroke="var(--p-safety)" stroke-width="2.2"/>
      <text class="legend-text" x="28" y="0">Bad sequence (losses early)</text>
      <line x1="200" x2="222" y1="-4" y2="-4" stroke="var(--p-highdebt)" stroke-width="2.2"/>
      <text class="legend-text" x="228" y="0">Good sequence (losses late)</text>
    </g>`;
  renderSVG(containerId, F.W, F.H, F.frame + refLine + refLabel + goodLine + badLine + legend);
}

function ssaAdjustedBenefit(piaAtFRA, claimAge) {
  const a = Math.max(62, Math.min(70, Math.round(claimAge)));
  return piaAtFRA * (SSA_CLAIM_AGE_FACTOR[a] || 1.0);
}

function getMCBackend() {
  return window.__customMCBackend || { simulate: historicalCyclesSimulate };
}

