function renderHistoricalFanChart({ paths, horizonYears, pv, containerId }) {
  const H = horizonYears;
  // Per-year percentiles across cohorts.
  const p10 = [], p25 = [], p50 = [], p75 = [], p90 = [];
  for (let y = 0; y <= H; y++) {
    const col = paths.map(p => p[y]).sort((a, b) => a - b);
    const at = q => col[Math.floor(q * (col.length - 1))];
    p10.push(at(0.10));
    p25.push(at(0.25));
    p50.push(at(0.50));
    p75.push(at(0.75));
    p90.push(at(0.90));
  }
  const yMax = niceCeil(Math.max(pv, ...p90) * 1.05);
  const xLabels = [];
  for (let i = 0; i <= H; i++) xLabels.push(String(i));
  const F = chartFrame({ title: 'Historical cohort balances over horizon (real $) — fan of p10/p25/p50/p75/p90', xLabels, yMax, xTickEvery: Math.max(5, Math.round(H / 6)) });

  // Build band polygon: forward along upper, back along lower.
  function band(upper, lower) {
    const fwd = upper.map((v, i) => `${F.xScale(i).toFixed(1)},${F.yScale(v).toFixed(1)}`);
    const back = lower.slice().reverse().map((v, idx) => {
      const i = lower.length - 1 - idx;
      return `${F.xScale(i).toFixed(1)},${F.yScale(v).toFixed(1)}`;
    });
    return fwd.concat(back).join(' ');
  }
  const bandOuter = band(p90, p10);
  const bandInner = band(p75, p25);
  const medianLine = p50.map((v, i) => `${F.xScale(i).toFixed(1)},${F.yScale(v).toFixed(1)}`).join(' ');

  const startY = F.yScale(pv);
  const refLine = `<line class="grid-line" x1="${F.ML}" x2="${F.ML + F.PW}" y1="${startY}" y2="${startY}" stroke="var(--muted-soft)" stroke-dasharray="3 4"/>`;
  const refLabel = `<text class="axis-label" x="${F.ML + F.PW - 4}" y="${startY - 4}" text-anchor="end" fill="var(--muted)">Starting balance</text>`;

  const fanOuter = `<polygon points="${bandOuter}" fill="var(--accent)" fill-opacity="0.15" stroke="none"/>`;
  const fanInner = `<polygon points="${bandInner}" fill="var(--accent)" fill-opacity="0.28" stroke="none"/>`;
  const median = `<polyline points="${medianLine}" fill="none" stroke="var(--accent-dark)" stroke-width="2" stroke-linejoin="round"/>`;

  const legend = `
    <g transform="translate(${F.ML}, ${F.H - 8})">
      <rect x="0" y="-9" width="14" height="11" fill="var(--accent)" fill-opacity="0.15"/>
      <text class="legend-text" x="19" y="0">p10–p90</text>
      <rect x="86" y="-9" width="14" height="11" fill="var(--accent)" fill-opacity="0.28"/>
      <text class="legend-text" x="105" y="0">p25–p75</text>
      <line x1="172" x2="194" y1="-4" y2="-4" stroke="var(--accent-dark)" stroke-width="2"/>
      <text class="legend-text" x="200" y="0">median</text>
    </g>`;
  renderSVG(containerId, F.W, F.H, F.frame + refLine + refLabel + fanOuter + fanInner + median + legend);
}

function niceCeil(v) {
  if (v <= 0) return 1;
  const exp = Math.pow(10, Math.floor(Math.log10(v)));
  const m = v / exp;
  let nice;
  if (m <= 1) nice = 1;
  else if (m <= 2) nice = 2;
  else if (m <= 5) nice = 5;
  else nice = 10;
  return nice * exp;
}

function chartFrame({ title, xLabels, yMax, yTicks = 5, xTickEvery }) {
  const W = 600, H = 320;
  const ML = 60, MR = 16, MT = 24, MB = 38;
  const PW = W - ML - MR;
  const PH = H - MT - MB;
  const xScale = i => ML + (xLabels.length > 1 ? (i / (xLabels.length - 1)) * PW : PW / 2);
  const yScale = v => MT + PH - (v / yMax) * PH;

  let frame = '';
  if (title) frame += `<text class="chart-title" x="${ML}" y="${MT - 8}">${title}</text>`;

  // Y grid + ticks
  for (let i = 0; i <= yTicks; i++) {
    const v = (yMax * i) / yTicks;
    const y = yScale(v);
    frame += `<line class="grid-line" x1="${ML}" x2="${ML + PW}" y1="${y}" y2="${y}"/>`;
    frame += `<text class="axis-label" x="${ML - 6}" y="${y + 3.5}" text-anchor="end">${fmtAxisMoney(v)}</text>`;
  }
  // X axis line
  frame += `<line class="axis-line" x1="${ML}" x2="${ML + PW}" y1="${MT + PH}" y2="${MT + PH}"/>`;
  // X tick labels
  const step = xTickEvery || Math.max(1, Math.round(xLabels.length / 8));
  for (let i = 0; i < xLabels.length; i += step) {
    const x = xScale(i);
    frame += `<line class="axis-line" x1="${x}" x2="${x}" y1="${MT + PH}" y2="${MT + PH + 4}"/>`;
    frame += `<text class="axis-label" x="${x}" y="${MT + PH + 16}" text-anchor="middle">${xLabels[i]}</text>`;
  }
  // Ensure last tick rendered
  if ((xLabels.length - 1) % step !== 0) {
    const i = xLabels.length - 1;
    const x = xScale(i);
    frame += `<line class="axis-line" x1="${x}" x2="${x}" y1="${MT + PH}" y2="${MT + PH + 4}"/>`;
    frame += `<text class="axis-label" x="${x}" y="${MT + PH + 16}" text-anchor="middle">${xLabels[i]}</text>`;
  }
  return { frame, W, H, ML, MR, MT, MB, PW, PH, xScale, yScale };
}

function renderSVG(containerId, viewBoxW, viewBoxH, inner) {
  const el = document.getElementById(containerId);
  if (!el) return;
  // Copy aria-label from wrapper to the svg itself so AT actually announces
  // the chart's purpose (wrapper-level aria-label on a roleless div is
  // inconsistently exposed by screen readers).
  const wrapperLabel = el.getAttribute('aria-label');
  const labelAttr = wrapperLabel ? ` aria-label="${wrapperLabel.replace(/"/g, '&quot;')}"` : '';
  el.innerHTML = `<svg viewBox="0 0 ${viewBoxW} ${viewBoxH}" role="img"${labelAttr}>${inner}</svg>`;
}

const SSA_CLAIM_AGE_FACTOR = {
  62: 0.700, 63: 0.750, 64: 0.800, 65: 0.867, 66: 0.933,
  67: 1.000, 68: 1.080, 69: 1.160, 70: 1.240
};

function historicalCyclesSimulate(params) {
  const { pv, annualWithdrawal, stockAlloc, horizonYears, strategy = 'fixed', streams = [], capeAdjustment = 0 } = params;
  const bondAlloc = 1 - stockAlloc;
  const lastStartIdx = HIST_RETURNS.length - horizonYears;
  if (lastStartIdx < 0) return { cycles: [], successRate: 0, percentiles: {}, note: 'horizon exceeds dataset' };

  // CL329 — Pre-compute per-year guaranteed-income (real $) so the strategy
  // adjustments compare against the *portfolio* withdrawal need, not the
  // headline withdrawal need.
  function guaranteedIncomeAtYear(y) {
    let total = 0;
    for (const s of streams) {
      if (y >= (s.startYearOffset || 0)) total += (s.annualReal || 0);
    }
    return total;
  }

  const cycles = [];
  const paths = [];
  for (let startIdx = 0; startIdx <= lastStartIdx; startIdx++) {
    let bal = pv;
    let realWithdrawal = annualWithdrawal;
    // Initial portfolio-only withdrawal rate uses year-1 guaranteed income.
    const initialPortfolioNeed = Math.max(0, annualWithdrawal - guaranteedIncomeAtYear(0));
    const initialWR = pv > 0 ? initialPortfolioNeed / pv : 0;
    let prevPortRet = 0;
    let depleted = null;
    const path = [pv];

    for (let y = 0; y < horizonYears; y++) {
      const yr = HIST_RETURNS[startIdx + y];
      // CL370/CL373 — apply CAPE adjustment only to first 10 years of stock returns.
      // The mean-reversion in equity valuations affects the early portion of a
      // cohort's return sequence; by year 10+, valuations have typically reverted
      // enough that the conditional effect on annual returns is small. Pfau 2012
      // documents the effect predominantly in the first decade.
      const capeShift = (y < 10) ? capeAdjustment : 0;
      const stockRet = (yr[1] / 100) + capeShift;
      const bondRet = yr[2] / 100;
      const portRet = stockAlloc * stockRet + bondAlloc * bondRet;

      const yearGuaranteed = guaranteedIncomeAtYear(y);
      let portfolioNeed = Math.max(0, realWithdrawal - yearGuaranteed);

      if (strategy === 'flexible' && prevPortRet < 0) {
        portfolioNeed = portfolioNeed * 0.75;
      } else if (strategy === 'guardrails' && bal > 0) {
        const currentWR = portfolioNeed / bal;
        if (currentWR > initialWR * 1.2) portfolioNeed = portfolioNeed * 0.9;
        else if (currentWR < initialWR * 0.8) portfolioNeed = portfolioNeed * 1.1;
      }
      bal -= portfolioNeed;
      if (bal < 0) {
        depleted = y + 1;
        bal = 0;
        // Pad remaining years with $0 so the path is full-length.
        while (path.length <= horizonYears) path.push(0);
        break;
      }
      bal *= 1 + portRet;
      prevPortRet = portRet;
      path.push(bal);
      // realWithdrawal stays in real $ across years (historical returns already real)
    }

    cycles.push({ startYear: HIST_RETURNS[startIdx][0], endingBalance: bal, depleted });
    paths.push(path);
  }

  const successes = cycles.filter(c => !c.depleted).length;
  const successRate = successes / cycles.length;
  const sortedEnds = cycles.map(c => c.endingBalance).sort((a, b) => a - b);
  const pct = p => sortedEnds[Math.floor(p * (sortedEnds.length - 1))];
  const percentiles = { p10: pct(0.10), p25: pct(0.25), p50: pct(0.50), p75: pct(0.75), p90: pct(0.90) };

  // Identify worst cycles (failed cycles or lowest ending balance)
  const failures = cycles.filter(c => c.depleted).map(c => c.startYear);
  return { cycles, successRate, percentiles, failures, totalCycles: cycles.length, paths };
}

function fmtAxisMoney(v) {
  const a = Math.abs(v);
  if (a >= 1e9) return '$' + (v / 1e9).toFixed(1) + 'B';
  if (a >= 1e6) return '$' + (v / 1e6).toFixed(1) + 'M';
  if (a >= 1e3) return '$' + Math.round(v / 1e3) + 'K';
  if (a === 0)  return '$0';
  return '$' + Math.round(v);
}

// Run every wire fn against the (now in-DOM) active view; each no-ops where its
// inputs are absent (getElementById → null guards). wireInlineCalculators scans a
// container for the inline "match" calc used in node details / the charts.
export function wireSectionCalculators(container) {
  for (const w of [wireMathCalculators, wireSpendingEssentialsCalculators, wireSpendingLifestyleCalculators, wirePortfolioCalculators, wireZeitgeistCalculators]) {
    try { w(); } catch (e) { /* view lacks these inputs */ }
  }
  try { wireInlineCalculators(container || document); } catch (e) { /* noop */ }
  // Initial paint: v1 computed each calc once inside renderX(); we inject the section
  // HTML directly, so we compute here. Call each wired calc SYNCHRONOUSLY (not via the
  // 80ms input-debounce). A deferred timer would otherwise fire AFTER a fast tab-switch
  // wiped #app and write to a now-missing output element (getElementById(...).innerHTML
  // on null → TypeError). Each call is guarded — a calc whose inputs aren't in the active
  // view simply no-ops. Real user input still flows through the debounced listeners above.
  for (const fn of [calcCompound, calcRule72, calcSavingsRate, calcRealNominal, calcSequence, calcMuniTEY, calcAssetLocation, calcHistoricalCycles, calcRentVsBuy, calcVehicleTCO, calcHDHPvsPPO, calcDIME, calcDI, calcDCFSA, calcSubscription, calcLifestyleCreep, calcExpenseRatio, calcEfficientFrontier, calcSharpe, calcCoastFIRE, calcDividend, calcDieWithZero]) {
    try { fn(); } catch (e) { /* this calc's view isn't mounted */ }
  }
}
